using ARS.Core; using UnityEditor; using UnityEditor.Build.Reporting;
namespace ARS.Editor { public static class BuildScript { public static void BuildAndroid(){PlayerSettings.productName=AppConfig.AppName;PlayerSettings.SetApplicationIdentifier(BuildTargetGroup.Android,AppConfig.PackageId);PlayerSettings.Android.minSdkVersion=AndroidSdkVersions.AndroidApiLevel24;PlayerSettings.Android.targetArchitectures=AndroidArchitecture.ARM64;PlayerSettings.SetScriptingBackend(BuildTargetGroup.Android,ScriptingImplementation.IL2CPP);var r=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/Scenes/SampleScene.unity"},locationPathName="Builds/ARashak.apk",target=BuildTarget.Android});if(r.summary.result!=BuildResult.Succeeded)throw new System.Exception("Android build failed: "+r.summary.result);} } }
